import{_ as r,C as n,o as l,c as s,a9 as d,E as i,j as e,a as o}from"./chunks/framework.asyjyako.js";const f=JSON.parse('{"title":"Understand the result","description":"","frontmatter":{},"headers":[],"relativePath":"guide/understanding-measurements.md","filePath":"guide/understanding-measurements.md","lastUpdated":null}'),m={name:"guide/understanding-measurements.md"};function p(c,a,h,u,g,b){const t=n("DocMedia");return l(),s("div",null,[a[0]||(a[0]=d('<p><a id="Understand-performance-measurements"></a></p><h1 id="Understand-the-result" tabindex="-1">Understand the result <a class="header-anchor" href="#Understand-the-result" aria-label="Permalink to &quot;Understand the result {#Understand-the-result}&quot;">​</a></h1><p>What each number means, and when two numbers may be compared. <a id="Wall-time:-how-long-the-operation-takes"></a></p><h2 id="Wall-time" tabindex="-1">Wall time <a class="header-anchor" href="#Wall-time" aria-label="Permalink to &quot;Wall time {#Wall-time}&quot;">​</a></h2><p>Elapsed clock time across the measured operation, including any waiting inside it.</p><ul><li><p>The workload definition decides the boundary. Read it before interpreting a timing.</p></li><li><p>Units: 1 s = 1,000 ms = 1,000,000 µs = 1,000,000,000 ns.</p></li><li><p><strong>CPU time</strong> counts processor execution. Threads consume it in parallel, and waiting uses none.</p></li></ul><p><a id="Samples,-repetitions-and-distributions"></a></p><h2 id="Samples-and-distributions" tabindex="-1">Samples and distributions <a class="header-anchor" href="#Samples-and-distributions" aria-label="Permalink to &quot;Samples and distributions {#Samples-and-distributions}&quot;">​</a></h2><ul><li><p>A <strong>sample</strong> is one measured execution (or a batch normalized per evaluation).</p></li><li><p><code>samples</code> is how many to collect; <code>evals</code> is evaluations per sample.</p></li><li><p><strong>median</strong> — middle value; the usual summary.</p></li><li><p><strong>minimum</strong> — fastest observed.</p></li><li><p><strong>mean</strong> — sensitive to slow samples.</p></li><li><p><strong>p95 / p99</strong> — thresholds covering about 95% / 99% of observations.</p></li></ul><p>A small microbenchmark does not establish a production p99. That needs production-like input, concurrency and load. <a id="Allocated-bytes,-allocation-count-and-live-memory"></a></p><h2 id="Allocations-and-memory" tabindex="-1">Allocations and memory <a class="header-anchor" href="#Allocations-and-memory" aria-label="Permalink to &quot;Allocations and memory {#Allocations-and-memory}&quot;">​</a></h2><ul><li><p><strong>Allocated bytes</strong> — memory obtained during the operation.</p></li><li><p><strong>Allocation count</strong> — how many allocation events occurred.</p></li><li><p><strong>Live memory</strong> — memory still retained afterwards.</p></li></ul><p>Allocated bytes, allocation count and live memory are three separate quantities. One large buffer can allocate more bytes than many small objects; many small objects cost more management work. Neither equals resident process memory. See <a href="./../process-memory">Process memory</a>. <a id="Garbage-collection:-reclaiming-unused-objects"></a></p><h2 id="Garbage-collection" tabindex="-1">Garbage collection <a class="header-anchor" href="#Garbage-collection" aria-label="Permalink to &quot;Garbage collection {#Garbage-collection}&quot;">​</a></h2><ul><li><p>The GC reclaims managed memory the program no longer needs; collecting it is work.</p></li><li><p><strong>GC time</strong> — measured collection time, in the same unit as the timing (BenchmarkTools).</p></li><li><p><strong>GC fraction</strong> — that time divided by elapsed time (Chairmarks).</p></li></ul><p>Never merge the two.</p><ul><li><p>Zero recorded GC time in a short sample does not mean zero allocations — the collector may simply not have run.</p></li><li><p>Do not add GC time to elapsed time; the elapsed interval already contains it.</p></li></ul><p><a id="Warm-code,-first-calls-and-state"></a></p><h2 id="Warm-and-cold-code" tabindex="-1">Warm and cold code <a class="header-anchor" href="#Warm-and-cold-code" aria-label="Permalink to &quot;Warm and cold code {#Warm-and-cold-code}&quot;">​</a></h2><ul><li><p>Julia compiles methods on first call.</p></li><li><p>A <strong>warm</strong> benchmark measures repeated execution after preparation.</p></li><li><p>A <strong>cold</strong> or first-call experiment must include the startup, loading or compilation boundary explicitly.</p></li></ul><p>Warm latency says nothing about <code>using YourPackage</code>. <a id="Flame-graphs:-where-sampled-work-accumulates"></a></p><h2 id="Flame-graphs" tabindex="-1">Flame graphs <a class="header-anchor" href="#Flame-graphs" aria-label="Permalink to &quot;Flame graphs {#Flame-graphs}&quot;">​</a></h2><ul><li><p>A <strong>call stack</strong> is the chain of calls leading to the current function.</p></li><li><p>A <strong>flame graph</strong> aggregates many stacks into nested rectangles.</p></li><li><p>Width — the selected weight (CPU samples, task samples or allocation bytes).</p></li><li><p>Depth — the calling relationship. Horizontal position is not a timeline.</p></li><li><p>A wide parent includes its descendants. Do not add parent and child percentages.</p></li></ul><p>CPU, wall-time and allocation flame graphs look similar but weight different things. Read the metric, unit and legend first. <a id="Inspect-three-recorded-Bibliography-profiles"></a></p><p>Inspect the <a href="/PerfChecker/dev/guide/investigate#Recorded-examples">three recorded Bibliography profiles</a> to compare CPU, wall-time and allocation weights on the same workload. <a id="Read-a-result-across-several-tools"></a></p><h2 id="Comparability" tabindex="-1">Comparability <a class="header-anchor" href="#Comparability" aria-label="Permalink to &quot;Comparability {#Comparability}&quot;">​</a></h2><p>Compare two numbers only when their measurement definitions and comparison keys agree. A run records the conditions so a consumer can check.</p><ul><li><p>Different OS, architecture, Julia threads or hardware make a comparison <strong>incomparable</strong>.</p></li><li><p>A changed runtime or environment is a <strong>warning</strong>.</p></li><li><p>A missing measurement stays missing. It never becomes an improvement.</p></li></ul><p><a id="Try-it-with-Bibliography"></a></p><h2 id="Recorded-examples" tabindex="-1">Recorded examples <a class="header-anchor" href="#Recorded-examples" aria-label="Permalink to &quot;Recorded examples {#Recorded-examples}&quot;">​</a></h2>',30)),i(t,{src:"/examples/bibliography/figures/history-time.svg",alt:"Bibliography export medians across nine tagged versions on a linear microsecond axis",caption:"One hundred samples per tag, Windows, Julia 1.13.0, one worker thread. Inputs match; the dependency stack evolves with the tags. Lower means less elapsed time."}),i(t,{src:"/examples/bibliography/figures/history-samples.svg",alt:"Nine groups containing all 900 export timings, with median markers and visible slow samples",caption:"Each dot is one sample; the dark marks are medians. Horizontal displacement only separates dots. Overlap and slow observations remain visible."}),i(t,{src:"/examples/bibliography/figures/history-memory.svg",alt:"Allocated bytes per Bibliography export across nine tags, from 4480 bytes at 0.1.0 to 8352 at 0.4.0",caption:"Julia allocation activity per operation. These values are neither retained heap size nor resident process memory. All nine points come from recorded measurements."}),a[1]||(a[1]=e("h2",{id:"Next",tabindex:"-1"},[o("Next "),e("a",{class:"header-anchor",href:"#Next","aria-label":'Permalink to "Next {#Next}"'},"​")],-1)),a[2]||(a[2]=e("ul",null,[e("li",null,[e("p",null,[e("a",{href:"./../reference/checks"},"Collectors"),o(" — what each tool records.")])]),e("li",null,[e("p",null,[e("a",{href:"./investigate"},"Investigate a change"),o(" — locate the cost with a profile.")])])],-1))])}const k=r(m,[["render",p]]);export{f as __pageData,k as default};
